SELECT id2, id4, CASE WHEN (avg(CAST(v1 AS DOUBLE)*CAST(v1 AS DOUBLE))-avg(CAST(v1 AS DOUBLE))*avg(CAST(v1 AS DOUBLE))) * (avg(CAST(v2 AS DOUBLE)*CAST(v2 AS DOUBLE))-avg(CAST(v2 AS DOUBLE))*avg(CAST(v2 AS DOUBLE))) = 0 THEN 0 ELSE (avg(CAST(v1 AS DOUBLE)*CAST(v2 AS DOUBLE))-avg(CAST(v1 AS DOUBLE))*avg(CAST(v2 AS DOUBLE))) * (avg(CAST(v1 AS DOUBLE)*CAST(v2 AS DOUBLE))-avg(CAST(v1 AS DOUBLE))*avg(CAST(v2 AS DOUBLE))) / ((avg(CAST(v1 AS DOUBLE)*CAST(v1 AS DOUBLE))-avg(CAST(v1 AS DOUBLE))*avg(CAST(v1 AS DOUBLE))) * (avg(CAST(v2 AS DOUBLE)*CAST(v2 AS DOUBLE))-avg(CAST(v2 AS DOUBLE))*avg(CAST(v2 AS DOUBLE)))) END AS r2 FROM groupby GROUP BY id2, id4;
